result.output:
139		}
140	
141		outputDir, values, err := s.resolveCreate(req)
142		if err != nil {
143			writeError(w, http.StatusUnprocessableEntity, err.Error())
144			return
145		}
146	
147		s.createMu.Lock()
148		defer s.createMu.Unlock()
149	
150		prep, err := template.PrepareCreate(r.Context(), template.CreateOptions{
151			Template:      name,
152			Version:       s.templates.version,
153			SetValues:     values,
154			UserAgent:     s.templates.userAgent,
155			Owner:         s.templates.owner,
156			Repo:          s.templates.repo,
157			GitHubBaseURL: s.templates.githubBaseURL,
158		})
159		if err != nil {
160			writeError(w, createErrorStatus(err), err.Error())
161			return
162		}
163		defer prep.Cleanup()
164	
165		var logs bytes.Buffer
166		result, err := template.RunCreate(prep, outputDir, req.Force, &logs)
167		if err != nil {
168			writeError(w, createErrorStatus(err), err.Error())
169			return
170		}
171		result.OutputDir = s.relPath(result.OutputDir)
172		writeJSON(w, http.StatusCreated, createResponse{
173			CreateResult: result,
174			Diagnostics:  diagnosticLines(logs.String()),
175		})
176	}
