178	// resolveCreate folds the request into the output directory and value set
179	// `int create --name` would produce: name doubles as values.name and as the
180	// output directory under the workspace root, confined there so the endpoint
181	// can never write outside the tree the dashboard serves.
182	func (s *apiServer) resolveCreate(req createRequest) (string, map[string]any, error) {
183		if req.Name == "" {
184			return "", nil, errors.New("name is required")
185		}
186		if strings.ContainsAny(req.Name, `/\`) || req.Name == "." || req.Name == ".." {
187			return "", nil, fmt.Errorf("invalid name %q (must be a single path segment)", req.Name)
188		}
189	
190		values := req.Values
191		if values == nil {
192			values = map[string]any{}
193		}
194		// A template that does not declare `name` still gets the directory as
195		// values.name — the CLI's --name sugar. When the template does declare
196		// it, the form's value wins; the two are separate concerns.
197		if _, ok := values["name"]; !ok {
198			values["name"] = req.Name
199		}
200		for key := range values {
201			if isReservedValueKey(key) {
202				return "", nil, fmt.Errorf("value %q is reserved and cannot be supplied", key)
203			}
204		}
205	
206		outputDir := filepath.Join(s.root, req.Name)
207		rootAbs, err := filepath.Abs(s.root)
208		if err != nil {
209			return "", nil, err
210		}
211		outAbs, err := filepath.Abs(outputDir)
212		if err != nil {
213			return "", nil, err
214		}
215		if outAbs != filepath.Join(rootAbs, req.Name) {
216			return "", nil, fmt.Errorf("invalid name %q (output would escape the workspace root)", req.Name)
217		}
218		return outputDir, values, nil
219	}
220	
221	// isReservedValueKey reports whether key is one of the reserved value keys a
222	// caller injects after resolution (topology, component, …). Users never
223	// supply them — a form value under one would collide with InjectReserved's
224	// refusal, so the endpoint refuses first with a message that says why.
225	func isReservedValueKey(key string) bool {
226		switch key {
227		case template.ReservedTopologyKey,
228			template.ReservedComponentKey,
229			template.ReservedGitopsKey,
230			template.ReservedScaffoldKey,
231			template.ReservedEnvKey:
232			return true
233		}
234		return false
235	}
