237	// templateFetchStatus maps a library fetch failure to the status the client
238	// can act on: an unknown template is a 404, anything upstream is a 502.
239	func templateFetchStatus(err error) int {
240		if strings.Contains(err.Error(), "not found in") {
241			return http.StatusNotFound
242		}
243		return http.StatusBadGateway
244	}
245	
246	// createErrorStatus maps a create failure to the status the form renders:
247	// unmet parameters and name conflicts are 422 (the form highlights fields),
248	// a non-empty output directory is 409 (the form offers force), and a fetch
249	// failure is 502. Everything else is a plain 500.
250	func createErrorStatus(err error) int {
251		msg := err.Error()
252		switch {
253		case strings.Contains(msg, "not empty"):
254			return http.StatusConflict
255		case strings.Contains(msg, "missing required parameter"),
256			strings.Contains(msg, "unknown parameter"),
257			strings.Contains(msg, "not found in"):
258			return http.StatusUnprocessableEntity
259		case strings.Contains(msg, "fetch"), strings.Contains(msg, "download"):
260			return http.StatusBadGateway
261		}
262		return http.StatusInternalServerError
263	}
