130	// newHandler wires the API routes and the SPA static handler onto a mux.
131	func newHandler(root, version string, p providers) (http.Handler, error) {
132		api := &apiServer{root: root, version: version, topo: p.topology, dep: p.deploy, templates: p.templates}
133		static, err := staticHandler()
134		if err != nil {
135			return nil, err
136		}
137	
138		mux := http.NewServeMux()
139		mux.HandleFunc("GET /api/health", api.health)
140		mux.HandleFunc("GET /api/integrations", api.listIntegrations)
141		mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
142		mux.HandleFunc("GET /api/catalog/{path...}", api.catalog)
143		mux.HandleFunc("GET /api/flow", api.flow)
144		mux.HandleFunc("GET /api/topology", api.topologies)
145		mux.HandleFunc("POST /api/topology/refresh", api.refreshTopologies)
146		// The verb carries the meaning rather than a /refresh segment: a {path...}
147		// wildcard has to be the last thing in the pattern. GET serves what has
148		// already been read, POST runs the command again.
149		mux.HandleFunc("GET /api/deploy/{path...}", api.getDeployState)
150		mux.HandleFunc("POST /api/deploy/{path...}", api.refreshDeployState)
151		// Template endpoints follow the same GET-read / POST-act split: list and
152		// show fetch the library release, create renders into the workspace.
153		mux.HandleFunc("GET /api/templates", api.listTemplates)
154		mux.HandleFunc("GET /api/templates/{name}", api.getTemplate)
155		mux.HandleFunc("POST /api/templates/{name}/create", api.createTemplate)
156		mux.Handle("/", static)
157		return mux, nil
158	}
