167	// listIntegrations mirrors `int list -o json` — the same scaffold entries in
168	// the same order — with the derived name/system fields added on top and each
169	// Path normalized to a root-relative identifier. The response is always an
170	// array (never null) even when empty.
171	func (s *apiServer) listIntegrations(w http.ResponseWriter, _ *http.Request) {
172		entries, systems := s.scan()
173		summaries := make([]integrationSummary, 0, len(entries))
174		for _, e := range entries {
175			summaries = append(summaries, s.summarize(e, systems))
176		}
177		writeJSON(w, http.StatusOK, summaries)
