180	// scan splits the workspace's scaffold entries for the API: the integration
181	// blocks to catalog, plus the declared systems keyed by their root directory
182	// (the directory holding a system-host scaffold). Support projects — the host
183	// and its shared contracts library — are infrastructure the system view
184	// already represents, not integrations to list.
185	func (s *apiServer) scan() (blocks []template.ScaffoldEntry, systems map[string]string) {
186		entries, _ := template.ListScaffolds(s.root)
187		systems = map[string]string{}
188		for _, e := range entries {
189			if e.Role == template.RoleSystemHost {
190				systems[filepath.Clean(filepath.Dir(e.Path))] = systemName(e)
191			}
192		}
193		blocks = entries[:0]
194		for _, e := range entries {
195			if e.Role == template.RoleSystemHost || e.Role == template.RoleSharedLibrary {
196				continue
197			}
198			blocks = append(blocks, e)
199		}
200		return blocks, systems
201	}
