203	// systemName is the name a system-host scaffold declares for its system
204	// (the template's `name` value, recorded at `sys create`), falling back to
205	// the host's parent directory name.
206	func systemName(host template.ScaffoldEntry) string {
207		if name, ok := host.Values["name"].(string); ok && name != "" {
208			return name
209		}
210		dir := filepath.Dir(host.Path)
211		if abs, err := filepath.Abs(dir); err == nil {
212			dir = abs
213		}
214		return filepath.Base(dir)
215	}
216	
217	// summarize derives an entry's tree coordinates from its path and the
218	// declared systems. A sibling system-host makes membership explicit: its
219	// declared name wins over the folder-derived one and applies even directly
220	// under the workspace root (where no folder-derived system exists).
221	// Otherwise the workspace root itself never counts as a system or domain, so
222	// an integration scaffolded at the root has neither and one directly under
223	// the root has a system but no domain. The served Path is made root-relative
224	// so it is a stable, URL-safe identifier regardless of whether the command
225	// was given a relative or absolute root (an absolute path would otherwise
226	// break detail lookups).
227	func (s *apiServer) summarize(e template.ScaffoldEntry, systems map[string]string) integrationSummary {
228		sum := integrationSummary{ScaffoldEntry: e, Name: filepath.Base(e.Path)}
229		sum.Path = s.relPath(e.Path)
230		path, root := filepath.Clean(e.Path), filepath.Clean(s.root)
231		parent := filepath.Dir(path)
232		if declared, ok := systems[parent]; ok && path != root {
233			sum.System = declared
234			sum.SystemPath = s.relPath(parent)
235			if grand := filepath.Dir(parent); parent != root && grand != root {
236				sum.Domain = filepath.Base(grand)
237			}
238			return sum
239		}
240		if path == root || parent == root {
241			return sum
242		}
243		sum.System = filepath.Base(parent)
244		sum.SystemPath = s.relPath(parent)
245		if grand := filepath.Dir(parent); grand != root {
246			sum.Domain = filepath.Base(grand)
247		}
248		return sum
249	}
