251	// relPath turns an entry's on-disk path into the root-relative, slash-separated
252	// identifier used in API responses and URLs. It falls back to the cleaned path
253	// so a value is always produced even if Rel fails (e.g. differing volumes).
254	func (s *apiServer) relPath(p string) string {
255		if rel, err := filepath.Rel(s.root, p); err == nil {
256			return filepath.ToSlash(rel)
257		}
258		return filepath.ToSlash(filepath.Clean(p))
259	}
