54	// buildTarGz packs entries (name → body) under a leading directory, the
55	// layout GitHub tarball responses and ExtractTarGz both expect.
56	func buildTarGz(t *testing.T, prefix string, entries map[string]string) []byte {
57		t.Helper()
58		var buf bytes.Buffer
59		gz := gzip.NewWriter(&buf)
60		tw := tar.NewWriter(gz)
61		for name, body := range entries {
62			if err := tw.WriteHeader(&tar.Header{
63				Name: prefix + "/" + name,
64				Mode: 0o644,
65				Size: int64(len(body)),
66			}); err != nil {
67				t.Fatal(err)
68			}
69			if _, err := tw.Write([]byte(body)); err != nil {
70				t.Fatal(err)
71			}
72		}
73		if err := tw.Close(); err != nil {
74			t.Fatal(err)
75		}
76		if err := gz.Close(); err != nil {
77			t.Fatal(err)
78		}
79		return buf.Bytes()
80	}
